const NALANDA_STATS=[{label:"Active Years",value:"~770"},{label:"Peak Scholars",value:"10,000+"},{label:"Monasteries (Viharas)",value:"11"},{label:"Countries Represented",value:"10+"}],NALANDA_BUILDINGS=[{id:"stupa-sariputta",name:"Great Stupa of Sariputta",type:"Monument",period:"3rd century BCE core, expanded through Gupta era",desc:"The site's oldest and most monumental structure, built in successive layers over centuries around a core commemorating Sariputta, one of the Buddha's chief disciples, who was born and died nearby.",details:"Excavations revealed at least seven rebuilding phases, with the final structure rising over 30 feet, surrounded by smaller votive stupas and a grand staircase flanked by sculpted niches of the Buddha."},{id:"vihara-complex",name:"Monastery Complex (Viharas 1–11)",type:"Residential & Teaching",period:"5th – 12th century CE",desc:"A row of eleven numbered monasteries forming the residential and instructional heart of the university, each built around a central courtyard with monks' cells on all four sides.",details:"Each vihara had two storeys of small cells for monks and students, a shrine room, and a communal courtyard used for teaching, debate, and daily rituals. Several show evidence of rebuilding after fire damage."},{id:"temple-site-3",name:"Temple Site No. 3",type:"Monument",period:"Gupta to Pala era, multiple rebuilding phases",desc:"The most spectacular structure at Nalanda: a massive stepped temple rebuilt at least seven times, each new phase constructed directly over the previous one without demolishing it.",details:"The final visible phase features ornate stucco figures of the Buddha and Bodhisattvas around its base and a monumental staircase, evidence of continuous royal patronage across dynasties."},{id:"dharmaganja",name:"Dharmaganja (The Great Library)",type:"Library",period:"5th – 12th century CE",desc:"Nalanda's legendary library complex, comprising three multi-storeyed buildings — Ratnasagara ('Sea of Jewels'), Ratnodadhi ('Ocean of Jewels'), and Ratnaranjaka ('Jewel-adorned') — said to have housed hundreds of thousands of manuscripts.",details:"Chinese pilgrim accounts describe Ratnodadhi as nine storeys tall, holding sacred texts, commentaries, and works on grammar, logic, medicine, and astronomy. The library reportedly burned for months when Nalanda was destroyed."},{id:"lecture-halls",name:"Lecture Halls & Debate Courtyards",type:"Teaching",period:"5th – 12th century CE",desc:"Open courtyards and covered halls distributed across the monastery complex where teachers lectured and students engaged in formal philosophical debate, a core part of the Nalanda curriculum.",details:"Contemporary accounts describe over a hundred lectures given daily on subjects ranging from Buddhist scripture and Sanskrit grammar to logic (hetuvidya), medicine, and mathematics."},{id:"residential-cells",name:"Monk & Student Residential Cells",type:"Residential",period:"5th – 12th century CE",desc:"Small individual cells lining the inner walls of each monastery courtyard, each fitted with a stone platform bed, niches for lamps, and storage for manuscripts and personal belongings.",details:"Rigorous entrance examinations were required for admission; contemporary accounts note that only a fraction of applicants were admitted, and students who failed the gatekeeper's oral test were turned away."}],NALANDA_SCHOLARS=[{id:"nagarjuna",name:"Nagarjuna",role:"Founder of Madhyamaka Philosophy",era:"c. 2nd century CE (predates formal university, later venerated there)",bio:"Though he lived before Nalanda's formal founding, Nagarjuna's Madhyamaka ('Middle Way') philosophy became foundational to the curriculum, and later tradition closely associates his teachings with the monastic lineage centered at Nalanda."},{id:"dharmapala",name:"Dharmapala",role:"Abbot and Logician",era:"6th century CE",bio:"A native of Kanchipuram who became one of Nalanda's most celebrated abbots, renowned for his commentaries on Buddhist logic and his debates that drew scholars from across the subcontinent."},{id:"silabhadra",name:"Silabhadra",role:"Head Abbot, Teacher of Xuanzang",era:"7th century CE",bio:"The revered head of Nalanda during Xuanzang's visit, said to be over 100 years old at the time. He personally tutored Xuanzang for years in Yogacara philosophy, an encounter recorded in exceptional detail in Chinese travel accounts."},{id:"dignaga",name:"Dignaga",role:"Founder of Buddhist Logic (Pramana)",era:"5th – 6th century CE",bio:"Associated with Nalanda's intellectual tradition, Dignaga systematized Buddhist epistemology and logic, laying groundwork that shaped centuries of philosophical debate at the university."},{id:"shantideva",name:"Shantideva",role:"Philosopher-Monk",era:"8th century CE",bio:"A Nalanda monk best known for composing the Bodhicharyavatara ('A Guide to the Bodhisattva's Way of Life'), a text still central to Mahayana Buddhist practice today."}],NALANDA_VISITORS=[{id:"xuanzang",name:"Xuanzang (Hiuen Tsang)",origin:"Tang China",period:"Studied at Nalanda c. 630s CE",account:"Spent around five years at Nalanda studying under Silabhadra. His travelogue, the Great Tang Records on the Western Regions, provides the single most detailed surviving account of the university's buildings, curriculum, and daily monastic life."},{id:"yijing",name:"Yijing (I-Tsing)",origin:"Tang China",period:"Studied at Nalanda c. 670s–680s CE",account:"A later Chinese pilgrim-scholar who studied and translated texts at Nalanda for roughly a decade, documenting its ordination rules, monastic discipline, and the daily routines of resident monks in meticulous detail."}],NALANDA_INTERNATIONAL=[{region:"Tang China",note:"Sent renowned pilgrim-scholars including Xuanzang and Yijing; Nalanda-trained monks carried Buddhist texts back to China."},{region:"Tibet",note:"Tibetan Buddhism's philosophical curriculum directly descends from Nalanda's teaching tradition, transmitted by later Indian masters."},{region:"Korea",note:"Korean monks are recorded among the international student body seeking Buddhist and Sanskrit learning."},{region:"Sri Lanka",note:"Sinhalese monks maintained close scholarly ties, with Sri Lankan royalty reportedly funding a monastery for Sinhalese students at Nalanda."},{region:"Srivijaya (Java & Sumatra)",note:"The maritime Srivijaya Empire sent students and sponsored monastic construction, reflecting Nalanda's reach across maritime Southeast Asia."},{region:"Central Asia",note:"Scholars from Central Asian Buddhist centers along the Silk Road traveled to Nalanda as part of a broader trans-Asian network of learning."}],NALANDA_TIMELINE=[{year:"c. 427 CE",title:"Foundation under Kumaragupta I",desc:"The Gupta emperor Kumaragupta I establishes the first monastery at Nalanda, beginning centuries of royal patronage."},{year:"5th – 6th c. CE",title:"Early expansion",desc:"Successive Gupta rulers and regional patrons fund additional viharas and temples, growing the site into a major monastic center."},{year:"c. 606 – 647 CE",title:"Harsha's patronage",desc:"Emperor Harshavardhana becomes a major benefactor, funding new construction and endowing the university with revenue from nearby villages."},{year:"c. 630s CE",title:"Xuanzang's residence",desc:"The Chinese pilgrim Xuanzang studies at Nalanda under Silabhadra, later producing the most detailed surviving eyewitness account."},{year:"c. 670s–680s CE",title:"Yijing's residence",desc:"Yijing documents monastic discipline and daily routines during his decade of study and translation work at Nalanda."},{year:"8th – 12th c. CE",title:"Pala dynasty patronage",desc:"The Pala kings become Nalanda's principal patrons, expanding the campus and supporting its role as the region's foremost Buddhist university."},{year:"c. 1193 CE",title:"Destruction",desc:"Nalanda is sacked during Bakhtiyar Khalji's campaigns in Bihar; the library complex is said to have burned for months, and the resident monastic community is dispersed."},{year:"1861 CE",title:"Rediscovery",desc:"Archaeologist Alexander Cunningham identifies the site's mounds as the ruins of Nalanda based on descriptions in Xuanzang's travelogue."},{year:"1915 – 1937 CE",title:"Systematic excavation",desc:"The Archaeological Survey of India conducts extensive excavations, uncovering the monastery and temple complexes visible today."},{year:"2016 CE",title:"UNESCO World Heritage status",desc:"The Archaeological Site of Nalanda Mahavihara is inscribed as a UNESCO World Heritage Site."}],NALANDA_ARCHAEOLOGY=[{title:"Excavated Area",detail:"Roughly 12 hectares of the site have been excavated by the ASI, though scholars estimate the full ancient campus was substantially larger and remains partly unexplored beneath modern land use."},{title:"Seal of Nalanda",detail:"Clay seals bearing the inscription 'Sri-Nalandaya Mahavihariya Arya-Bhikshu-Sanghasya' ('of the community of noble monks of the great monastery of Nalanda') confirmed the site's identity beyond doubt."},{title:"Nalanda Archaeological Museum",detail:"Located adjacent to the ruins, the ASI museum houses sculptures, bronzes, seals, and manuscripts recovered from excavations, including notable Buddhist and Hindu iconography reflecting the site's long occupation."},{title:"Xuanzang Memorial Hall",detail:"A memorial hall near the site, built with Chinese government support, commemorates Xuanzang's residence and the historic scholarly exchange between India and China."},{title:"Stratigraphic Evidence",detail:"Multiple rebuilding layers at Temple Site No. 3 and the Great Stupa provide physical evidence of centuries of continuous use, destruction by fire, and reconstruction under successive dynasties."}],NALANDA_REFERENCES=[{text:"Archaeological Survey of India — Nalanda Mahavihara Excavation Reports.",url:"https://asi.nic.in/"},{text:"UNESCO World Heritage Centre — Archaeological Site of Nalanda Mahavihara.",url:"https://whc.unesco.org/en/list/1502/"},{text:"Beal, Samuel (trans.). Si-Yu-Ki: Buddhist Records of the Western World (Xuanzang's travelogue). 1884.",url:"https://www.jstor.org/"},{text:"Dutt, Sukumar. Buddhist Monks and Monasteries of India. George Allen & Unwin, 1962.",url:"https://www.jstor.org/"}];